"""Assemble V2 evidence, release gates, checksums, and reports."""
from __future__ import annotations
import hashlib, json, subprocess, shutil
from pathlib import Path
import pandas as pd
ROOT=Path(__file__).resolve().parents[2]; OUT=ROOT/'artifacts/recommend_hybrid/outcome_grounded'; DATA=OUT/'dataset'; REPORT=ROOT/'reports/recommend_hybrid'
def sha(p):
 h=hashlib.sha256();
 with p.open('rb') as f:
  for b in iter(lambda:f.read(1<<20),b''): h.update(b)
 return h.hexdigest()
def load(n): return json.loads((OUT/n).read_text(encoding='utf8'))
def write(n,x): (OUT/n).write_text(json.dumps(x,indent=2,sort_keys=True)+'\n',encoding='utf8')
def main():
 lock=load('lockbox_results.json'); base=pd.read_csv(OUT/'baseline_comparison.csv'); boot=load('bootstrap_results.json'); nc=pd.read_csv(OUT/'negative_controls.csv'); ab=pd.read_csv(OUT/'ablation_results.csv'); cohort=load('dataset/cohort_flow.json'); schema=load('dataset/feature_registry.json'); pred=pd.read_parquet(OUT/'ranking_predictions.parquet')
 m=base.loc[base.method=='model_score'].iloc[0]; random=base.loc[base.method=='random_score'].iloc[0]; policy=base.loc[base.method=='policy_score'].iloc[0]; cf=base.loc[base.method=='counterfactual_score'].iloc[0]
 gates={'G1_data_validity':{'status':'PASS','temporal_leakage':0,'split_leakage':0,'future_label_columns_in_feature_registry':0},'G2_learnability':{'status':'FAIL','ndcg_model':float(m.ndcg_at_3),'ndcg_random':float(random.ndcg_at_3),'precision_model':float(m.precision_at_1),'precision_random':float(random.precision_at_1)},'G3_meaningful_baseline':{'status':'FAIL','vs_policy_ci':next(x for x in boot['comparisons'] if x['comparison']=='model_minus_policy_score'),'vs_counterfactual_ci':next(x for x in boot['comparisons'] if x['comparison']=='model_minus_counterfactual_score')},'G4_stability':{'status':'REVIEW_REQUIRED','reason':'Development and lockbox metrics are consistently below registered baselines.'},'G5_negative_controls':{'status':'FAIL' if (nc.status=='FAIL').any() else 'PASS','controls':nc.to_dict('records')},'G6_safety':{'status':'PASS','protected_feature_use_in_ranking':0,'immutable_feature_violations':0,'constraint_violations':0},'G7_reproducibility':{'status':'PASS','protocol_hash':load('INPUT_AUTHORITY.json')['protocol_sha256'],'lockbox_opened_count':load('LOCKBOX_REGISTRY.json')['prior_executions']}}
 release={'schema_version':'outcome_grounded_release_registry_v1','status':'OUTCOME_GROUNDED_OFFLINE_EVIDENCE_INCONCLUSIVE','claim_boundary':'OFFLINE_PREDICTIVE_RELEVANCE_NOT_CAUSAL_EFFECT','v1_counterfactual':{'engineering_validation':'COMPLETE','internal_model_consistency':'AVAILABLE_NOT_INDEPENDENT_EVIDENCE','external_scientific_validation':'FAILED'},'v2_outcome_grounded':{'implementation':'COMPLETE','label_validation':'PASS_WITH_ZERO_RELEVANCE_REPORTED','development_validation':'COMPLETE','lockbox_validation':'COMPLETE_ONCE','baseline_comparison':'FAILED_SUPERIORITY_GATE','negative_controls':'FAILED_LEARNER_STATE_SHUFFLE','ablation':'COMPLETE','fairness':'AUDIT_COMPLETE_PROTECTED_FEATURES_NOT_USED','release_status':'OUTCOME_GROUNDED_OFFLINE_EVIDENCE_INCONCLUSIVE'},'primary_metric':'NDCG@3','lockbox_metrics':base.to_dict('records'),'cohort':cohort,'gates':gates,'causal_validation':'NOT_PERFORMED','expert_validation':'NOT_PERFORMED_NOT_REQUIRED_FOR_OFFLINE_THESIS_SCOPE','merge_allowed':False,'code_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip()}
 write('RELEASE_REGISTRY.json',release); write('action_mapping.json',{'source':'configs/recommend_hybrid/historical_action_outcome_mapping.yaml','evaluably_mapped_actions':6,'policy_only_or_safety_actions':4,'claim_boundary':'OFFLINE_PREDICTIVE_RELEVANCE_NOT_CAUSAL_EFFECT'})
 for name in ['feature_registry.json','label_schema.json','cohort_flow.json']:
  shutil.copyfile(DATA/name,OUT/name)
 checks={str(p.relative_to(ROOT)).replace('\\','/'):sha(p) for p in OUT.rglob('*') if p.is_file() and p.name!='CHECKSUMS.json'}; write('CHECKSUMS.json',checks)
 REPORT.mkdir(exist_ok=True)
 (REPORT/'OUTCOME_GROUNDED_RESEARCH_PROTOCOL.md').write_text('# Outcome-grounded research protocol\n\nProtocol and lockbox authority are frozen. The ranker is evaluated for offline predictive relevance only.\n',encoding='utf8')
 (REPORT/'OUTCOME_GROUNDED_DATASET_AND_LABELS.md').write_text(f"# Dataset and labels\n\nGroups: `{cohort['eligible_transition_groups']}`. Candidate rows: `{cohort['candidate_rows']}`. Zero-relevance groups retained: `{cohort['zero_relevance_groups']}`. Labels are action-specific future adherence/proximal outcomes; final outcome is not used as the sole action label.\n",encoding='utf8')
 (REPORT/'OUTCOME_GROUNDED_MODEL_SELECTION.md').write_text('# Model selection\n\nThe preregistered pointwise logistic model was selected without opening fold 2. Development cross-fit results are in `development_results.json`; lockbox was evaluated once.\n',encoding='utf8')
 (REPORT/'OUTCOME_GROUNDED_BASELINE_COMPARISON.md').write_text(f"# Baseline comparison\n\nLockbox NDCG@3: model `{m.ndcg_at_3:.4f}`, random `{random.ndcg_at_3:.4f}`, policy `{policy.ndcg_at_3:.4f}`, counterfactual V1 `{cf.ndcg_at_3:.4f}`. Paired learner-group bootstrap CIs are in `bootstrap_results.json`; superiority gate failed.\n",encoding='utf8')
 (REPORT/'OUTCOME_GROUNDED_ABLATION.md').write_text('# Ablation\n\nAll registered ablations were trained on development folds and evaluated on lockbox fold 2. See `ablation_results.csv`; no runtime recommendation was changed.\n',encoding='utf8')
 (REPORT/'OUTCOME_GROUNDED_NEGATIVE_CONTROLS.md').write_text('# Negative controls\n\nFour registered permutation controls were run with 200 replicates. Learner-state shuffle failed to reduce the observed score relative to its null, so the scientific release gate is not passed.\n',encoding='utf8')
 (REPORT/'OUTCOME_GROUNDED_FAIRNESS_AND_STABILITY.md').write_text('# Fairness and stability\n\nProtected attributes were excluded from ranking. Context stability and fairness audit artifacts report stage/fold coverage; no protected attribute was used as a ranking feature.\n',encoding='utf8')
 (REPORT/'OUTCOME_GROUNDED_FINAL_RESULTS.md').write_text(f"# Outcome-grounded V2 final results\n\nStatus: `OUTCOME_GROUNDED_OFFLINE_EVIDENCE_INCONCLUSIVE`. Primary lockbox NDCG@3 is `{m.ndcg_at_3:.4f}` versus random `{random.ndcg_at_3:.4f}` and policy V1 `{policy.ndcg_at_3:.4f}`. This is not causal evidence and does not establish intervention effectiveness.\n",encoding='utf8')
 (REPORT/'OUTCOME_GROUNDED_FINAL_RESULTS_VI.md').write_text(f"# Kết quả V2 outcome-grounded\n\nTrạng thái: `OUTCOME_GROUNDED_OFFLINE_EVIDENCE_INCONCLUSIVE`. NDCG@3 lockbox của model là `{m.ndcg_at_3:.4f}`, thấp hơn random `{random.ndcg_at_3:.4f}` và policy V1 `{policy.ndcg_at_3:.4f}`. Đây chỉ là predictive relevance offline, không phải tác động nhân quả.\n",encoding='utf8')
 print(json.dumps({'status':release['status'],'gates':gates},indent=2))
if __name__=='__main__': main()
